require 'thread'

class Counter
  def initialize(initial_value = 0)
    @value = initial_value
    @mutex = Mutex.new
  end

  def value
    @mutex.synchronize { @value }
  end

  def increment
    @mutex.synchronize { @value += 1 }
  end

  def decrement
    @mutex.synchronize { @value -= 1 }
  end
end
